/**
 * Find a matching KB entry for a given user query string.
 * Returns the entry or null if no match is found.
 * @param {string} query
 * @returns {object|null}
 */
export function findStaticKBAnswer(query) {
  if (!query || typeof query !== 'string') return null;
  // Normalize: lowercase + strip punctuation
  const lower = query.toLowerCase().replace(/[?!.,;]/g, ' ');

  for (const entry of ORION_STATIC_KB) {
    // Check exactWords first (must appear as whole word, e.g. "hi" won't match "satkhira")
    if (entry.exactWords) {
      if (entry.exactWords.some((w) => new RegExp(`\\b${w}\\b`).test(lower))) {
        return entry;
      }
    }

    for (const kw of entry.keywords) {
      const kwLower = kw.toLowerCase();

      // 1. Fast path: exact substring
      if (lower.includes(kwLower)) return entry;

      // 2. All words of multi-word keyword present anywhere (order-independent)
      const kwWords = kwLower.split(/\s+/).filter(Boolean);
      if (kwWords.length > 1 && kwWords.every((w) => lower.includes(w))) {
        return entry;
      }
    }
  }
  return null;
}
